    @Test
    void validacao_ModalidadeInvalida() {
        ResumoRequest request = new ResumoRequest();
        request.setItens(Arrays.asList(
                new ResumoRequest.ItemRequest("Camiseta", new BigDecimal("79.90"), 1, new BigDecimal("0.30"))
